import CoreLocation

/// An independent restaurant with cited evidence, from `IndependentGrades.json`
/// (generated by scripts/build_independents.py from docs/data/independent_evidence.json).
nonisolated struct IndependentGrade: Codable, Sendable, Identifiable {
    let id: String
    let name: String
    let aliases: [String]?
    let city: String?
    let latitude: Double
    let longitude: Double
    let grade: String
    let confidence: GradeConfidence
    let basis: String
    let sources: [GradeSource]

    var rating: SlopRating { SlopRating(rawValue: grade) ?? .notGraded }

    var location: CLLocation { CLLocation(latitude: latitude, longitude: longitude) }
}

/// Looks up evidence-backed grades for independents. Names aren't unique, so a
/// place must match by name *and* be within `maxDistance` of the entry.
nonisolated struct IndependentGradeStore: Sendable {
    static let maxDistance: CLLocationDistance = 250
    static let shared = IndependentGradeStore()

    let entries: [IndependentGrade]

    init(resource: String = "IndependentGrades", bundle: Bundle = .main) {
        guard let url = bundle.url(forResource: resource, withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let items = try? JSONDecoder().decode([IndependentGrade].self, from: data) else {
            entries = []
            return
        }
        entries = items
    }

    init(entries: [IndependentGrade]) {
        self.entries = entries
    }

    func match(name: String, coordinate: CLLocationCoordinate2D) -> IndependentGrade? {
        let place = CLLocation(latitude: coordinate.latitude, longitude: coordinate.longitude)
        let candidates = Set(ChainDatabase.candidateTokens(for: name).map(Self.core))
        return entries
            .filter { $0.location.distance(from: place) <= Self.maxDistance }
            .first { entry in
                ([entry.name] + (entry.aliases ?? [])).contains { candidates.contains(Self.core(ChainDatabase.tokens($0))) }
            }
    }

    /// Tokens without trailing descriptors, so "Screen Door Restaurant" is "screen door".
    private static func core(_ tokens: [String]) -> [String] {
        var core = tokens
        while core.count > 1, let last = core.last, ChainDatabase.descriptors.contains(last) {
            core.removeLast()
        }
        return core
    }
}
